const $=id=>document.getElementById(id),v=$('video'),rail=$('rail'); let words=[],crop=0,drag=null,windowStart=0,windowEnd=7200; fetch('/media/transcript.json').then(r=>r.json()).then(x=>words=x).catch(()=>{}); const t=n=>new Date(Math.max(0,n)*1000).toISOString().slice(11,19); function bounds(){let duration=v.duration||7200,span=duration/Number($('zoom').value);windowStart=Math.max(0,Math.min(duration-span,v.currentTime-span/2));windowEnd=windowStart+span} function x(time){return (time-windowStart)/(windowEnd-windowStart)*100} function draw(time=v.currentTime){bounds();$('clock').textContent=t(time);$('bounds').textContent=t(windowStart)+' – '+t(windowEnd);let a=Number($('start').value),b=Number($('end').value);$('selection').style.left=x(a)+'%';$('selection').style.width=(x(b)-x(a))+'%';$('cursor').style.left=x(time)+'%';$('state').textContent=`Corte ${t(a)} – ${t(b)} · crop ${crop.toFixed(0)}%`;let lo=0,hi=words.length;while(lo<hi){let mid=(lo+hi)>>1;if(words[mid].start<=time)lo=mid+1;else hi=mid}let n=Math.max(0,lo-1),base=Math.floor(n/4)*4;$('caption').innerHTML=words.slice(base,base+4).map((w,i)=>`<span class="word ${base+i===n?'active':''}">${w.text}</span>`).join(' ')} function frame(now,meta){draw(meta.mediaTime);v.requestVideoFrameCallback(frame)} if(v.requestVideoFrameCallback)v.requestVideoFrameCallback(frame);else v.ontimeupdate=()=>draw(); $('play').onclick=()=>{if(!v.paused){v.pause();return}let a=Number($('start').value),b=Number($('end').value);if(v.currentTime<a||v.currentTime>=b)v.currentTime=a;v.play()};v.addEventListener('timeupdate',()=>{if(v.currentTime>=Number($('end').value)&&!v.paused)v.pause();draw()});for(const id of ['start','end','zoom'])$(id).oninput=()=>draw();$('source').onchange=()=>{let current=v.currentTime;v.src='/media/'+$('source').value;v.onloadedmetadata=()=>{v.currentTime=current;v.onloadedmetadata=null;draw()}}; function seek(e){let box=rail.getBoundingClientRect(),value=windowStart+(e.clientX-box.left)/box.width*(windowEnd-windowStart);return Math.max(0,Math.min(v.duration||7200,value))}rail.onpointerdown=e=>{drag=e.target.id==='left'?'start':e.target.id==='right'?'end':'seek';rail.setPointerCapture(e.pointerId);move(e)};rail.onpointermove=e=>{if(drag)move(e)};rail.onpointerup=()=>drag=null;function move(e){let value=seek(e);if(drag==='seek')v.currentTime=value;else if(drag==='start')$('start').value=Math.min(value,Number($('end').value)-.033).toFixed(3);else $('end').value=Math.max(value,Number($('start').value)+.033).toFixed(3);draw()} let down; $('preview').onpointerdown=e=>{down={x:e.clientX,crop};e.currentTarget.setPointerCapture(e.pointerId)};$('preview').onpointermove=e=>{if(!down)return;crop=Math.max(-50,Math.min(50,down.crop+(e.clientX-down.x)/3));v.style.left=(50+crop)+'%';draw()};$('preview').onpointerup=()=>down=null;draw();
$('bench').onclick=async()=>{if(!v.requestVideoFrameCallback){$('benchResult').textContent='requestVideoFrameCallback indisponível';return} v.pause();let out=[];for(let i=0;i<30;i++){let target=(i+.37)*(v.duration-1)/30,at=performance.now();let result=await new Promise((resolve,reject)=>{let timer=setTimeout(()=>reject(Error('Tempo esgotado')),10000);v.requestVideoFrameCallback(function next(now,m){if(Math.abs(m.mediaTime-target)>.05){v.requestVideoFrameCallback(next);return}clearTimeout(timer);resolve({pedido:target,quadro:m.mediaTime,latenciaMs:now-at,erroMs:(m.mediaTime-target)*1000})});v.currentTime=target});out.push(result);$('benchResult').textContent=`${i+1}/30 buscas`; }let sorted=out.map(r=>r.latenciaMs).sort((a,b)=>a-b),mean=sorted.reduce((a,b)=>a+b,0)/sorted.length,p95=sorted[Math.ceil(.95*sorted.length)-1];$('benchResult').textContent=`média ${mean.toFixed(1)} ms; p95 ${p95.toFixed(1)} ms`;let data={arquivo:$('source').value,agente:navigator.userAgent,resultados:out};if(new URLSearchParams(location.search).has('measure')){await fetch('/__measurement',{method:'POST',body:JSON.stringify(data)});return}let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='buscas-'+$('source').value+'.json';a.click()};

if(new URLSearchParams(location.search).has('measure')){let which=new URLSearchParams(location.search).get('measure');if(which==='proxy'){$('source').value='proxy.mp4';v.src='/media/proxy.mp4'}v.addEventListener('loadedmetadata',async()=>{await $('bench').onclick();$('benchResult').textContent+=' — coleta concluída';if(which==='proxy'){v.muted=true;$('end').value=65;v.currentTime=0;v.addEventListener('seeked',()=>{v.play();let stats={frames:0,wrong:0,first:null,last:null};function sample(now,m){if(stats.first===null)stats.first=m.mediaTime;stats.last=m.mediaTime;stats.frames++;let active=[...document.querySelectorAll('.word')].findIndex(e=>e.classList.contains('active'));if(active!==Math.floor(m.mediaTime/.3)%4)stats.wrong++;if(m.mediaTime<60)v.requestVideoFrameCallback(sample);else{v.pause();fetch('/__sync',{method:'POST',body:JSON.stringify(stats)})}}v.requestVideoFrameCallback(sample)},{once:true})}},{once:true})}
